import * as THREE from 'three/webgpu';
import { texture, uv, vec2, add, mul, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const atlasW = 512;
  const atlasH = 320;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;

  const width = 1.8;
  const height = width / aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const offsetU = rect.x / atlasW;
  const offsetV = 1.0 - (rect.y + rect.h) / atlasH;
  const scaleU = rect.w / atlasW;
  const scaleV = rect.h / atlasH;

  const uvOffset = uniform(vec2(offsetU, offsetV));
  const uvScale = uniform(vec2(scaleU, scaleV));

  const remappedUV = add(mul(uv(), uvScale), uvOffset);

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = map;
  material.mapNode = texture(map, remappedUV);
  material.transparent = true;
  material.toneMapped = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-collection-card-2-image';

  const node = new THREE.Object3D();
  node.name = 'hub-collection-card-2';
  node.add(mesh);

  node.position.set(3.2, -0.3, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  node.userData.handlers = {};

  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
  };

  // billboard toward camera each frame via ctx render loop hook if available
  if (ctx && typeof ctx.onBeforeRender === 'function') {
    const billboardFn = (camera) => {
      if (camera) mesh.quaternion.copy(camera.quaternion);
    };
    ctx.onBeforeRender(billboardFn);
    const prevCleanup = node.userData.cleanup;
    node.userData.cleanup = () => {
      prevCleanup();
      if (typeof ctx.offBeforeRender === 'function') {
        ctx.offBeforeRender(billboardFn);
      }
    };
  }

  return node;
}
